import { timingSafeEqual as nodeTimingSafeEqual } from "node:crypto";

export function timingSafeEqual(a: string, b: string): boolean {
  const aBuf = new TextEncoder().encode(a);
  const bBuf = new TextEncoder().encode(b);
  return nodeTimingSafeEqual(aBuf, bBuf);
}

// Jitter delay helper for rate limiting
let lastDelayTime = 0;

export function getJitterDelay(minMs: number, maxMs: number): number {
  // Calculate base delay with jitter
  const baseDelay = minMs + Math.random() * (maxMs - minMs);

  // Apply jitter to prevent timing attacks
  const now = Date.now();
  const timeSinceLast = now - lastDelayTime;
  const jitter = Math.min(50, Math.max(0, 50 - timeSinceLast));

  const delay = baseDelay + jitter;
  lastDelayTime = now + delay;

  return delay;
}

